const fs = require('fs');
const path = require('path');

const now = new Date();
const buildInfo = {
  buildDateIso: now.toISOString(),
  buildDateReadable: now.toString(),
};

const targetDir = path.join(__dirname, '..', 'frontend', 'app');
const targetPath = path.join(targetDir, 'build-info.generated.ts');

const fileContents = `// AUTO-GENERATED: Do not edit manually.
// Generated by scripts/generate-build-info.js
export const buildInfo = ${JSON.stringify(buildInfo, null, 2)} as const;
`;

fs.mkdirSync(targetDir, { recursive: true });
fs.writeFileSync(targetPath, fileContents);
console.log(`Build info written to ${targetPath}`);
